// Concatenates the migrations (except the cron one) into supabase/setup-all.sql
// for pasting into the Supabase SQL Editor. Run: node scripts/build-setup-sql.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';

const dir = new URL('../supabase/migrations/', import.meta.url);
const files = readdirSync(dir).filter((f) => f.endsWith('.sql') && !f.endsWith('_cron.sql')).sort();
const parts = [
  '-- MealTrack: all schema migrations in one file, for pasting into the Supabase SQL Editor.',
  '-- Generated by scripts/build-setup-sql.mjs from supabase/migrations (excluding the cron migration;',
  '-- run that separately after setting the Vault secrets). Run on a NEW project only.',
];
for (const f of files) parts.push('', `-- ==== supabase/migrations/${f} ====`, readFileSync(new URL(f, dir), 'utf8'));
writeFileSync(new URL('../supabase/setup-all.sql', import.meta.url), parts.join('\n'));
console.log(`setup-all.sql written from ${files.length} migrations:\n  ${files.join('\n  ')}`);
